/** Engine role to illustrated character. Generated cases reuse the same four actors and the victim. */
export const ROLE_ART:Record<string,string>={S1:"Qadir",S2:"Vale",S3:"Okafor",S4:"Pike",V:"Harlow"};
export function characterArt(role:string):CharacterArt|null {
  const art=CAST_ART[ROLE_ART[role]||role];return art&&(art.frames.neutral||art.frames.standing)?art:null;}
/** Always some art: an unknown role borrows Vale's figure rather than drawing nothing. */
export function actorArt(role:string):CharacterArt {return characterArt(role)||CAST_ART[ROLE_ART.S2];}
export function frameArt(art:CharacterArt,frame:ArtFrame):FrameArt {return art.frames[frame]||art.frames.neutral||art.frames.standing!;}
/** Frame size in cm at real scale. */
export function frameSizeCm(f:FrameArt):{w:number;h:number} {return {w:f.canvas[0]/ART_PX_PER_CM,h:f.canvas[1]/ART_PX_PER_CM};}
/** A normalised point as cm from the feet pivot: x to the image's right, y up. */
export function anchorCm(f:FrameArt,p:ArtPoint):{x:number;y:number} {const s=frameSizeCm(f);return {x:(p.x-f.feet.x)*s.w,y:(f.feet.y-p.y)*s.h};}
/** A normalised box as cm from the feet pivot: left/right/bottom/top. */
export function boxCm(f:FrameArt,b:ArtBox):{left:number;right:number;bottom:number;top:number} {const s=frameSizeCm(f);return {left:(b.x-f.feet.x)*s.w,right:(b.x+b.w-f.feet.x)*s.w,bottom:(f.feet.y-b.y-b.h)*s.h,top:(f.feet.y-b.y)*s.h};}
/** Heights above the feet (cm) that staging uses instead of the Run 8 hard-coded card numbers. */
export interface StageHeights {face:number;eyes:number;chin:number;facing:number;chest:number;thread:number;spotlight:number;token:number;subtitle:number;top:number;width:number}
export function stageHeights(role:string):StageHeights {
  const art=actorArt(role),f=frameArt(art,"neutral"),face=boxCm(f,f.faceBox),eyes=anchorCm(f,f.eyes).y,s=frameSizeCm(f);
  const chin=face.bottom,mid=(face.bottom+face.top)/2;
  return {face:mid,eyes,chin,facing:chin-12,chest:chin-30,thread:chin-30,spotlight:chin-32,token:chin-12,subtitle:chin-9,top:face.top+4,width:s.w};}
